parameters.jsCode:
const body = $node['Inbound Website Lead Webhook'].json.body || {};
const enrichment = $input.first().json || {};

let score = 50;

// Score on Budget
if (body.budget && (body.budget.includes('40,000') || body.budget.includes('100,000'))) {
  score += 30;
} else if (body.budget && body.budget.includes('15,000')) {
  score += 20;
} else {
  score += 10;
}

// Score on Company Domain
const domain = body.website || (body.email ? body.email.split('@')[1] : '');
if (domain && !domain.includes('gmail') && !domain.includes('yahoo')) {
  score += 15;
}

score = Math.min(score, 99);

return [{
  json: {
    leadId: `lead_${Date.now()}`,
    name: body.name || 'Anonymous Prospect',
    email: body.email || 'lead@domain.com',
    company: body.company || enrichment.company?.name || 'Self-Employed',
    website: body.website || enrichment.company?.domain || 'N/A',
    budget: body.budget || '$10,000+',
    services: body.services || ['full_suite'],
    leadScore: score,
    isHighPriority: score >= 80,
    submittedAt: new Date().toISOString()
  }
}];

